		/** 
		 * Tests creating a new Observation.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Observation");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Observation" );

			try {            
				Observation entity = ObservationService.getObservationInstance().createObservation( generateNewEntity() );
				thePrimaryKey = entity.getObservationId();
				LOGGER.info( "-- Successfully created a Observation with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Observation. 
		 */
		public Observation testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Observation" );

			Observation entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Observation with primary key" );
			msg.append( thePrimaryKey );
			
			ObservationFetchOneSummary fetchOneSummary = new ObservationFetchOneSummary( thePrimaryKey );

			try {
				entity = ObservationService.getObservationInstance().getObservation( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Observation " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Observation.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Observation." );

			StringBuilder msg = new StringBuilder( "Failed to update a Observation : " );        
			Observation entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Observation." );

				// for use later on...
				thePrimaryKey = entity.getObservationId();

				ObservationService proxy = ObservationService.getObservationInstance();            
				proxy.updateObservation( entity );   

				LOGGER.info( "-- Successfully saved Observation - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Observation.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Observation." );

			try{
			    Observation entity = testRead(); 
				ObservationService.getObservationInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Observation with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Observation with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Observations.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Observations:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Observation : " );        
			List<Observation> collection  = null;

			try {
				// call the static get method on the ObservationService
				collection = ObservationService.getObservationInstance().getAllObservation();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Observation entity = null;            
					Iterator<Observation> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getObservationId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

